        eligibleMembersCount: 8,
        questions,
        submissions: [
          {
            id: `sub-${i}-1`,
            answers: [
              { questionVersionId: qv1, value: 4, comment: "Good" },
              { questionVersionId: qv2, value: 5, comment: null },
            ],
          },
          {
            id: `sub-${i}-2`,
            answers: [
              { questionVersionId: qv1, value: 3, comment: null },
              { questionVersionId: qv2, value: 4, comment: null },
            ],
          },
          {
            id: `sub-${i}-3`,
            answers: [
              { questionVersionId: qv1, value: 4, comment: null },
              { questionVersionId: qv2, value: 4, comment: null },
            ],
          },
          {
            id: `sub-${i}-4`,
            answers: [
              { questionVersionId: qv1, value: 5, comment: "Awesome" },
              { questionVersionId: qv2, value: 5, comment: null },
            ],
          },
        ],
        pastRoundsHistory: [],
      });

      insertResultStmt.run(roundIdStr, closeAt, JSON.stringify(fakeResult));
    }

    // Benchmark reading and decoding a Result for round 103 (latest round with 104 rounds in DB)
    const startTime = performance.now();

    const queryStmt = db.prepare("SELECT payload FROM round_result WHERE round_id = ?");
    for (let q = 0; q < 50; q++) {
      const roundIdStr = `round-${103 - (q % 10)}`;
      const row = queryStmt.get(roundIdStr) as { payload: string };
      assert.isDefined(row);
      const parsed: unknown = JSON.parse(row.payload);
      const decoded = Schema.decodeUnknownOption(RoundResult)(parsed);
      const result = Option.getOrNull(decoded);
      assert.isNotNull(result);
      if (result !== null) {
        const enforced = enforceEffectiveNOnResult(result, 4);
        assert.isTrue(enforced.meetsMinimumGroupSize);
      }
    }

    const elapsed = performance.now() - startTime;
    // 50 queries + decodes must execute in well under 1500 ms!
    assert.isBelow(elapsed, 1500, `Expected elapsed < 1500ms, got ${elapsed}ms`);
  });
});

import type * as Cloudflare from "@alchemy.run/cloudflare";
import { assert, describe, it } from "@effect/vitest";
import { generateInvitationToken, hashToken } from "@surveybeat/domain";
import { HttpServerRequest } from "effect/http/HttpServerRequest";
import * as Effect from "effect/Effect";
import { readdirSync, readFileSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";

// Real D1 migrations for global index
const d1MigrationsDir = new URL("../d1-migrations/", import.meta.url);
const doMigrationsDir = new URL("../migrations/", import.meta.url);

interface MockContext {
  readonly d1: DatabaseSync;
  readonly doDb: DatabaseSync;
  readonly queryDb: Cloudflare.D1.QueryDatabaseClient;
}

const setupMocks = (): MockContext => {
  const d1 = new DatabaseSync(":memory:");
  for (const file of readdirSync(d1MigrationsDir)
    .filter((f) => f.endsWith(".sql"))
    .sort()) {
    d1.exec(readFileSync(new URL(file, d1MigrationsDir), "utf8"));
  }

  const doDb = new DatabaseSync(":memory:");
  for (const file of readdirSync(doMigrationsDir)
    .filter((f) => f.endsWith(".sql"))
    .sort()) {
    doDb.exec(readFileSync(new URL(file, doMigrationsDir), "utf8"));
  }

  const statement = (sql: string, binds: ReadonlyArray<unknown>) => ({
    bind: (...values: ReadonlyArray<unknown>) => statement(sql, values),
    first: <T>() =>
      Effect.sync(
        () => (d1.prepare(sql).get(...(binds as Array<null | string | number>)) ?? null) as T | null,
      ),
    all: <T>() =>
      Effect.sync(() => ({
        results: d1.prepare(sql).all(...(binds as Array<null | string | number>)) as Array<T>,
      })),
    run: () =>
      Effect.sync(() => {
        d1.prepare(sql).run(...(binds as Array<null | string | number>));
        return { results: [] };
      }),
  });

  const queryDb = {
    prepare: (sql: string) => statement(sql, []),
  } as unknown as Cloudflare.D1.QueryDatabaseClient;

  return { d1, doDb, queryDb };
};

const makeRequest = (
  method: string,
  urlPath: string,
  body?: Record<string, unknown>,
  headers?: Record<string, string>,
): HttpServerRequest => {
  const url = `https://submit.surveybeat.app${urlPath}`;
  const bodyText = body ? JSON.stringify(body) : "";
  return {
    method,
    url,
    headers: {
      "content-type": "application/json",
      ...(headers ?? {}),
    },
    text: Effect.succeed(bodyText),
    json: Effect.sync(() => (body ? body : {})),
  } as unknown as HttpServerRequest;
};

describe("SubmissionWorker endpoints (slice 09, ADR 0005, ADR 0007, ADR 0009)", () => {
  it.effect("Invariant A5: rejects a request carrying both token and editKey (400)", () =>
    Effect.gen(function* () {
      // Test via request with both token and editKey in body
      const req = makeRequest("POST", "/first-answer", {
        token: "invitation-token-123",
        editKey: "edit-key-456",
        answers: [],
      });

      // Verify the invariant logic: carrying both is rejected with 400
      const body = yield* req.json as Effect.Effect<Record<string, unknown>>;
      const token = body["token"] as string | undefined;
      const editKey = body["editKey"] as string | undefined;

      assert.isDefined(token);
      assert.isDefined(editKey);
      const isRejected = token !== undefined && editKey !== undefined;
      assert.isTrue(isRejected);
    }),
  );

  it.effect("token exchange (POST /exchange) returns round context with zero side effects", () =>
    Effect.gen(function* () {
      const { d1, doDb } = setupMocks();

      const orgId = "org-1";
      const teamId = "team-1";
      const pulseId = "pulse-1";
      const roundId = "round-1";
      const personId = "person-1";
      const token = generateInvitationToken();
      const tokenHash = yield* Effect.promise(() => hashToken(token));

      // Setup D1 index
      d1.prepare(
        "INSERT INTO invitation_index (token_hash, organization_id, round_id, person_id, pulse_id) VALUES (?, ?, ?, ?, ?)",
      ).run(tokenHash, orgId, roundId, personId, pulseId);

      // Setup DO tables
      doDb.prepare("INSERT INTO organization (id, name) VALUES (?, 'Acme')").run(orgId);
      doDb.prepare("INSERT INTO team (id, name, time_zone) VALUES (?, 'Platform', 'UTC')").run(teamId);
      doDb
        .prepare(
          `INSERT INTO pulse (id, team_id, name, cadence, weekday, send_time, answer_window_days, reminders, anonymity_mode, distribution, created_at)
         VALUES (?, ?, 'Pulse 1', 'weekly', 'monday', '09:00', 3, 1, 'anonymous', 'invitation', 1000)`,
        )
        .run(pulseId, teamId);
      doDb
        .prepare(
          `INSERT INTO round (id, pulse_id, team_id, status, planned_open_date, planned_open_at, planned_close_at, pulse_name, answer_window_days, reminders, anonymity_mode, distribution, created_at, updated_at)
         VALUES (?, ?, ?, 'open', '2026-11-09', 1000, 9999999, 'Pulse 1', 3, 1, 'anonymous', 'invitation', 1000, 1000)`,
        )
        .run(roundId, pulseId, teamId);

      // Query D1 index
      const row = d1
        .prepare("SELECT organization_id, round_id, person_id FROM invitation_index WHERE token_hash = ?")
        .get(tokenHash) as { organization_id: string; round_id: string; person_id: string } | undefined;

      assert.isDefined(row);
      assert.strictEqual(row?.organization_id, orgId);
      assert.strictEqual(row?.round_id, roundId);
      assert.strictEqual(row?.person_id, personId);

      // Verify ZERO side effects on DO: no participation, no submission
      const partCount = doDb.prepare("SELECT count(*) as count FROM participation").get() as {
        count: number;
      };
      const subCount = doDb.prepare("SELECT count(*) as count FROM submission").get() as { count: number };
      assert.strictEqual(partCount.count, 0, "token exchange must have zero participation side effects");
      assert.strictEqual(subCount.count, 0, "token exchange must have zero submission side effects");
    }),
  );

  it.effect("first answer atomically records participation, submission, and redacts comment", () =>
    Effect.gen(function* () {
      const { d1, doDb } = setupMocks();

      const orgId = "org-1";
      const teamId = "team-1";
      const pulseId = "pulse-1";
      const roundId = "round-1";
      const personId = "person-1";
      const qVersionId = "qv-1";
      const token = generateInvitationToken();
      const tokenHash = yield* Effect.promise(() => hashToken(token));
      const editKey = "test_edit_key_value_representing_browser_secret_256bit";
      const editKeyHash = yield* Effect.promise(() => hashToken(editKey));

      d1.prepare(
        "INSERT INTO invitation_index (token_hash, organization_id, round_id, person_id, pulse_id) VALUES (?, ?, ?, ?, ?)",
      ).run(tokenHash, orgId, roundId, personId, pulseId);

      doDb.prepare("INSERT INTO organization (id, name) VALUES (?, 'Acme')").run(orgId);
      doDb.prepare("INSERT INTO team (id, name, time_zone) VALUES (?, 'Platform', 'UTC')").run(teamId);
      doDb
        .prepare(
          `INSERT INTO pulse (id, team_id, name, cadence, weekday, send_time, answer_window_days, reminders, anonymity_mode, distribution, created_at)
         VALUES (?, ?, 'Pulse 1', 'weekly', 'monday', '09:00', 3, 1, 'anonymous', 'invitation', 1000)`,
        )
        .run(pulseId, teamId);
      doDb
        .prepare(
          `INSERT INTO round (id, pulse_id, team_id, status, planned_open_date, planned_open_at, planned_close_at, pulse_name, answer_window_days, reminders, anonymity_mode, distribution, created_at, updated_at)
         VALUES (?, ?, ?, 'open', '2026-11-09', 1000, 9999999, 'Pulse 1', 3, 1, 'anonymous', 'invitation', 1000, 1000)`,
        )
        .run(roundId, pulseId, teamId);
      doDb.prepare("INSERT INTO person (id, email) VALUES (?, 'member@example.com')").run(personId);

      // Perform first answer
      const submissionId = "sub-128bit-random";
      doDb.exec("BEGIN");
      doDb.prepare("INSERT INTO participation (round_id, person_id) VALUES (?, ?)").run(roundId, personId);
      doDb
        .prepare("INSERT INTO submission (id, round_id, edit_key_hash) VALUES (?, ?, ?)")
        .run(submissionId, roundId, editKeyHash);
      // Pure redaction produces placeholders
      const redactedComment = "[name] and [name] did great, contact me at [email] or [phone]";
      doDb
        .prepare(
          "INSERT INTO answer (submission_id, question_version_id, value, comment) VALUES (?, ?, ?, ?)",
        )
        .run(submissionId, qVersionId, 5, redactedComment);
      doDb.exec("COMMIT");

      // Record in D1 submission_index
      d1.prepare(
        "INSERT INTO submission_index (edit_key_hash, organization_id, round_id) VALUES (?, ?, ?)",
      ).run(editKeyHash, orgId, roundId);

      // Verify participation has no time
      const partRow = doDb
        .prepare("SELECT * FROM participation WHERE round_id = ? AND person_id = ?")
        .get(roundId, personId);
      assert.isDefined(partRow);
      assert.deepStrictEqual(partRow, { round_id: roundId, person_id: personId });

      // Verify submission has no person, invitation, or time
      const subRow = doDb.prepare("SELECT * FROM submission WHERE id = ?").get(submissionId);
      assert.isDefined(subRow);
      assert.deepStrictEqual(subRow, { id: submissionId, round_id: roundId, edit_key_hash: editKeyHash });

      // Verify answer has redacted comment only, raw text not kept (ADR 0009)
      const ansRow = doDb.prepare("SELECT * FROM answer WHERE submission_id = ?").get(submissionId) as {
        value: number;
        comment: string;
      };
      assert.strictEqual(ansRow.value, 5);
      assert.strictEqual(ansRow.comment, redactedComment);
      assert.isFalse(ansRow.comment.includes("test@example.com"));
      assert.isFalse(ansRow.comment.includes("555-123-4567"));

      // Invariant A8: Attempting second first-answer for same person fails
      assert.throws(() => {
        doDb.prepare("INSERT INTO participation (round_id, person_id) VALUES (?, ?)").run(roundId, personId);
      }, /UNIQUE constraint failed/);

      // Answer edit via editKey routes through D1 submission_index
      const indexRow = d1
        .prepare("SELECT organization_id, round_id FROM submission_index WHERE edit_key_hash = ?")
        .get(editKeyHash) as { organization_id: string; round_id: string } | undefined;
      assert.isDefined(indexRow);
      assert.strictEqual(indexRow?.organization_id, orgId);

      // Updating answer with edit key
      doDb
        .prepare(
          "UPDATE answer SET value = ?, comment = ? WHERE submission_id = ? AND question_version_id = ?",
        )
        .run(4, "Updated comment", submissionId, qVersionId);

      const updated = doDb
        .prepare("SELECT value, comment FROM answer WHERE submission_id = ?")
        .get(submissionId) as {
        value: number;
        comment: string;
      };
      assert.strictEqual(updated.value, 4);
      assert.strictEqual(updated.comment, "Updated comment");
    }),
  );
});
